        anchor = ip
        # Consecutive repeats with zero literals refer to the second recent offset.
        while ip < limit and ip-rep[1] >= 0 and data[ip:ip+4] == data[ip-rep[1]:ip-rep[1]+4]:
            ml = length(ip-rep[1],ip)
