class EntropyTable:
    def __init__(self, symbols, log=None):
        self.log = (len(symbols)-1).bit_length() if log is None else log
        self.symbols = symbols
        counts = collections.Counter(symbols)
        nxt = dict(counts)
        self.rows = []
        self.by_symbol = collections.defaultdict(list)
        for i, s in enumerate(symbols):
            n = nxt[s]
            bits = self.log - (n.bit_length()-1)
            base = (n << bits) - (1 << self.log)
            self.rows.append((s, bits, base))
            self.by_symbol[s].append((i, bits, base))
            nxt[s] += 1
