LL_TABLE = EntropyTable([LL_BASE.index(v) for v in LL_STATES])
ML_TABLE = EntropyTable([ML_BASE.index(v) for v in ML_STATES])
OF_TABLE = EntropyTable(OF_STATES)
DEFAULT_TABLES = (LL_TABLE, OF_TABLE, ML_TABLE)

def table_from_normalized(norm, log):
    size = 1 << log
