    for sym, n in enumerate(norm):
        if n == -1:
            syms[high] = sym
            high -= 1
    step = (size >> 1) + (size >> 3) + 3
    pos = 0
    for sym, n in enumerate(norm):
        for _ in range(max(0, n)):
            syms[pos] = sym
            pos = (pos+step) & (size-1)
