class FrameHeader:
    def __init__(self, data, p=0):
        self.start = p
        if data[p:p+4] != MAGIC:
            raise CodecError('Unknown frame descriptor')
        p += 4
        if p >= len(data):
            raise CodecError('premature end',kind='truncated')
        flags = data[p]
        p += 1
        if flags & 8:
            raise CodecError('Unsupported frame parameter')
        single = bool(flags & 32)
        self.check = bool(flags & 4)
        self.window = 0
        dictsize = (0,1,2,4)[flags&3]
        fs = flags >> 6
        cssize = (1 if single else 0) if fs == 0 else (2 if fs == 1 else (4 if fs == 2 else 8))
        need = (0 if single else 1)+dictsize+cssize
        if p+need > len(data):
            raise CodecError('premature end',kind='truncated')
        if not single:
            wd = data[p]
            p += 1
            base = 1 << (10+(wd>>3))
            self.window = base+(base>>3)*(wd&7)
        self.dictid = int.from_bytes(data[p:p+dictsize], 'little')
        p += dictsize
        self.size = None
        if cssize:
            self.size = int.from_bytes(data[p:p+cssize], 'little')+(256 if cssize == 2 else 0)
            p += cssize
        if single:
            self.window = self.size
        self.end = p

def decode_zstd(data, check=True, dictionary=b'', max_window=1<<27, trace=None):
    p = 0
    output = bytearray()
    while p < len(data):
        if len(data)-p < 4:
            raise CodecError('unknown header',output,'format')
        magic = int.from_bytes(data[p:p+4],'little')
        if magic & 0xfffffff0 == 0x184d2a50:
            if p+8 > len(data):
                raise CodecError('premature end',output,'truncated')
            size = int.from_bytes(data[p+4:p+8], 'little')
            p += 8+size
            if p > len(data):
                raise CodecError('premature end',output,'truncated')
            continue
        if data[p:p+4] != MAGIC:
            raise CodecError('unsupported format',output,'format')
        try:
            h = FrameHeader(data,p)
            if h.window > max_window:
                raise CodecError('Frame requires too much memory for decoding', kind='memory',window=h.window)
            if h.dictid:
                if len(dictionary) < 8 or dictionary[:4] != bytes.fromhex('37a430ec') or int.from_bytes(dictionary[4:8],'little') != h.dictid:
                    raise CodecError('Dictionary mismatch')
            p = h.end
            history = bytearray(dictionary)
            start = len(history)
            reps = [1,4,8]
            tables = [None]*3
            huffman = None
            while True:
                if p+3 > len(data):
                    raise CodecError('premature end',history[start:],'truncated')
                bh = int.from_bytes(data[p:p+3], 'little')
                p += 3
                size,kind,last = bh >> 3,(bh >> 1)&3,bh&1
                stored = 1 if kind == 1 else size
                if p+stored > len(data):
                    raise CodecError('premature end',history[start:],'truncated')
                block = data[p:p+stored]
                p += stored
                if kind == 0:
                    history.extend(block)
                elif kind == 1:
                    history.extend(block*size)
                elif kind == 2:
                    reps,tables,huffman = decode_block(block,history,reps,tables,huffman,trace)
                else:
                    raise CodecError()
                if last:
                    break
            plain = bytes(history[start:])
            if h.size is not None and len(plain) != h.size:
                raise CodecError()
            if h.check:
                if p+4 > len(data):
                    raise CodecError('premature end',plain,'truncated')
                cs = int.from_bytes(data[p:p+4], 'little')
                p += 4
                if check and xxh64(plain)&0xffffffff != cs:
                    raise CodecError("Restored data doesn't match checksum")
            output.extend(plain)
        except CodecError as e:
            e.partial = bytes(output)+e.partial
            raise
        except (IndexError,ValueError,OverflowError,KeyError):
            raise CodecError(partial=output)
    return bytes(output)

def literals_raw(lit):
    n = len(lit)
    if n < 32:
        return bytes([n<<3])+lit
    if n < 4096:
        return ((n<<4)|4).to_bytes(2,'little')+lit
    return ((n<<4)|12).to_bytes(3,'little')+lit

def sequence_codes(seq):
    ll,ml,off = seq
    lc = bisect.bisect_right(LL_BASE,ll)-1
    mc = bisect.bisect_right(ML_BASE,ml)-1
    oc = off.bit_length()-1
    return lc,mc,oc,ll-LL_BASE[lc],ml-ML_BASE[mc],off-(1<<oc)

def encode_sequences(sequences):
    if not sequences:
        return b'\x00'
    codes = [sequence_codes(s) for s in sequences]
    ll_t,of_t,ml_t = DEFAULT_TABLES
    n = len(sequences)
    modes = 0
    prefix = b''
    # Constant alphabets are encoded directly when this saves their state bits.
    if n > 2:
        for j,shift in ((0,6),(2,4),(1,2)):
            symbols = [c[j] for c in codes]
            if len(set(symbols)) == 1:
                t = EntropyTable([symbols[0]],0)
                if j == 0: ll_t = t
                if j == 1: ml_t = t
                if j == 2: of_t = t
                modes |= 1 << shift
                prefix += bytes([symbols[0]])
    w = BitWriter()
    lc,mc,oc,le,me,oe = codes[-1]
    sl,sm,so = ll_t.initial(lc),ml_t.initial(mc),of_t.initial(oc)
    w.add(le,LL_BITS[lc]);w.add(me,ML_BITS[mc]);w.add(oe,oc)
    for lc,mc,oc,le,me,oe in reversed(codes[:-1]):
        so = of_t.encode(so,oc,w)
        sm = ml_t.encode(sm,mc,w)
        sl = ll_t.encode(sl,lc,w)
        w.add(le,LL_BITS[lc]);w.add(me,ML_BITS[mc]);w.add(oe,oc)
    w.add(sm,ml_t.log);w.add(so,of_t.log);w.add(sl,ll_t.log)
    if n < 128:
        hdr = bytes([n])
    elif n < 0x7f00:
        hdr = bytes([(n>>8)+128,n&255])
    else:
        hdr = b'\xff'+(n-0x7f00).to_bytes(2,'little')
    return hdr+bytes([modes])+prefix+w.finish()

def default_window(level):
    if level <= 1: return 19
    if level == 2: return 20
    if level <= 8: return 21
    if level <= 16: return 22
    if level <= 19: return 23
    return {20:25,21:26,22:27}.get(level,27)

def encode_header(size,check=True,windowlog=21,content_size=True,dictid=0):
    flag = 4 if check else 0
    if dictid:
        ds = 1 if dictid < 256 else (2 if dictid < 65536 else 4)
        flag |= {1:1,2:2,4:3}[ds]
    else:
        ds = 0
    single = size is not None and size <= (1 << windowlog) and content_size
    if single:
        flag |= 32
    if not content_size:
        size = None
    if size is None:
        cs = b''
    elif size < 256 and single:
        cs = bytes([size])
    elif size < 65792:
        flag |= 64
        cs = max(0,size-256).to_bytes(2,'little')
    elif size <= 0xffffffff:
        flag |= 128
        cs = size.to_bytes(4,'little')
    else:
        flag |= 192
        cs = size.to_bytes(8,'little')
    wd = b'' if single else bytes([(windowlog-10)*8])
    return MAGIC+bytes([flag])+wd+dictid.to_bytes(ds,'little')+cs


def find_sequences(data, level=3, dictionary=b'', start=0, end=None, reps=None):
    """Hash-indexed LZ parsing, with a recent-offset fast path."""
    if end is None:
