    table = {}
    # Index the available history. Keep only a small set of recent occurrences.
    begin = max(0,start-(1<<min(default_window(level),20)))
    for j in range(begin,min(start+1,n-3)):
        table[data[j:j+4]] = [j]
    ip = start+1 if start == 0 else start
    if level >= 18 and n-start < 256:
        table.clear()
    limit = n-8
    if level <= 1 or 5 <= level <= 16:
        limit = n-12
    def length(a,b):
        if a < 0:
            return 0
        maxn = n-b
        k = 0
        while k+16 <= maxn and data[a+k:a+k+16] == data[b+k:b+k+16]:
