        sequences.append((ll,ml,offcode))
        newpos = at+ml
        # Updating boundary positions is enough for the fast parser; more
        # thorough modes retain matches throughout the span.
        inds = range(ip+1,min(newpos,n-3)) if level >= 5 else (ip+1,newpos-2)
