def compress_zstd(data,level=3,known_size=True,check=True,content_size=True,windowlog=None,dictionary=b'',no_dictid=False,compress_literals=None):
    if level == 0:
        level = 3
    wlog = default_window(level) if windowlog is None else windowlog
    if known_size and data:
        wlog = min(wlog,max(10,(len(data)-1).bit_length()))
    cs = len(data) if known_size or not data else None
    out = bytearray(encode_header(cs,check,wlog,content_size))
    all_data = dictionary+data
    begin = len(dictionary)
    rep = [1,4,8]
    chunks = list(range(begin,len(all_data),131072)) or [begin]
    for bi,start in enumerate(chunks):
        end = min(start+131072,len(all_data))
        chunk = all_data[start:end]
        last = bi == len(chunks)-1
        if bi and chunk and chunk == chunk[:1]*len(chunk):
            out.extend(((len(chunk)<<3)|2|last).to_bytes(3,'little'))
            out.extend(chunk[:1])
            continue
        lit,seq,nrep = find_sequences(all_data,level,start=start,end=end,reps=rep)
        body = literals_raw(lit)+encode_sequences(seq)
        gain = (len(chunk) >> (6 if level >= 0 else 6))+2
        if len(body) < len(chunk)-gain:
            out.extend(((len(body)<<3)|4|last).to_bytes(3,'little'))
            out.extend(body)
            rep = nrep
        else:
            out.extend(((len(chunk)<<3)|last).to_bytes(3,'little'))
            out.extend(chunk)
    if check:
        out.extend((xxh64(data)&0xffffffff).to_bytes(4,'little'))
    return bytes(out)
