            mb = (e.window+1048575)//1048576
            self.err(f'{name} : Window size larger than maximum : {e.window} > {self.o.memory} \n',2)
            self.err(f'{name} : Use --long={max(10,(e.window-1).bit_length())} or --memory={mb}MB \n',2)
        elif e.kind == 'gzip-truncated':self.err(f'{name} : Read error : premature end \n')
        elif e.kind == 'gzip':self.err(f'{name} : gzip decompression error : incorrect data check \n')
        elif e.kind.startswith('lzma'):self.err(f'{name} : lzma decompression error \n')
        else:self.err(f'{name} : Decoding error (36) : {e} \n')
