                if v and not low <= v <= high:self.fatal('zstd: error 11 : Parameter is out of bound \n',11)
    def stat_input(self,p):
        if p == '-':return None
        if not self.o.force and os.path.islink(p):
            self.err(f'Warning : {p} is a symbolic link, ignoring \n',2);return False
        try:s = os.stat(p)
        except OSError as e:
            self.err(f"zstd: can't stat {p} : {e.strerror} -- ignored \n");return False
        if stat.S_ISDIR(s.st_mode):
            self.err(f'zstd: {p} is a directory -- ignored \n');return False
        if not (stat.S_ISREG(s.st_mode) or stat.S_ISFIFO(s.st_mode)) and not self.o.force:
            self.err(f'zstd: {p} is not a regular file -- ignored \n');return False
        return s
    def output_name(self,p):
        o = self.o
        if o.mode == 'test':return None
        if o.to_stdout or o.output == '-' or (p == '-' and not o.output):return '-'
        if o.output is not None:return o.output
        if o.mode == 'compress':
            name = p+FORMATS[o.fmt]
        else:
            suff = next((x for x in SUFFIXES if p.endswith(x)),None)
            if suff is None:
                self.err(f"zstd: {p}: unknown suffix (.zst/.tzst/.gz/.tgz/.lzma/.xz/.txz expected). Can't derive the output file name. Specify it with -o dstFileName. Ignoring.\n")
                return False
            name = p[:-len(suff)]+('.tar' if suff in ('.tzst','.tgz','.txz') else '')
        if o.outdir:
            if o.mirror:
                relative = name.lstrip('/')
                if relative.startswith('./'):relative = relative[2:]
                name = os.path.join(o.outdir,relative)
                try:os.makedirs(os.path.dirname(name),exist_ok=True)
                except OSError:pass
            else:name = os.path.join(o.outdir,os.path.basename(name))
        return name
    def allow_output(self,path,src):
        o = self.o
        if path in (None,'-'):return True
        if src != '-':
            try:
                if os.path.samefile(path,src):
                    self.err(f'zstd: {src} and {path} are the same file \n');return False
            except OSError:pass
        if os.path.lexists(path) and not o.force and not (os.path.exists(path) and stat.S_ISCHR(os.stat(path).st_mode)):
            if o.verbosity < 2 or src == '-':
                self.err(f'zstd: {path} already exists; not overwritten  \n');return False
            self.err(f'zstd: {path} already exists; overwrite (y/n) ? ')
            ans = sys.stdin.readline()
            if not ans.startswith(('y','Y')):
                self.err('Not overwritten  \n \n');return False
        return True
    def encode(self,data,known):
        o = self.o
        if o.fmt == 'gzip':
            level = min(9,o.level) if o.level > 0 else 6
            c = zlib.compressobj(level,zlib.DEFLATED,31)
            return c.compress(data)+c.flush()
        if o.fmt in ('xz','lzma'):
            level = min(9,o.level) if o.level > 0 else 6
            fmt = lzma.FORMAT_XZ if o.fmt == 'xz' else lzma.FORMAT_ALONE
            return lzma.compress(data,format=fmt,preset=level)
        if o.stream_size is not None:
            if len(data) != o.stream_size:self.fatal('zstd: error 11 : Src size is incorrect \n',11)
            known = True
        wl = o.zparams.get('wlog',0) or o.long or None
        if wl is None and o.size_hint:
            wl = min(default_window(o.level),max(10,(o.size_hint-1).bit_length()))
        return compress_zstd(data,level=o.level,known_size=known,check=o.check,content_size=o.content_size,
                             windowlog=wl,dictionary=self.dictionary,no_dictid=o.no_dictid,
                             compress_literals=o.compress_literals)
    def decode(self,data):
        o = self.o
        if not data:raise CodecError('unexpected end of file',kind='format')
        out = bytearray()
        p = 0
        passthrough = o.pass_through if o.pass_through is not None else (o.force and o.mode != 'test')
        while p < len(data):
            chunk = data[p:]
            magic = int.from_bytes(chunk[:4],'little')
            if chunk[:4] == MAGIC or magic & 0xfffffff0 == 0x184d2a50:
                try:
                    result = decode_zstd(chunk,check=o.check,dictionary=self.dictionary,max_window=o.memory or 1<<27)
                    out.extend(result)
                    break
                except CodecError as e:
                    e.partial = bytes(out)+e.partial
                    raise
            elif chunk.startswith(b'\x1f\x8b'):
                try:
                    d = zlib.decompressobj(31)
                    part = d.decompress(chunk)
                    if not d.eof:raise CodecError('premature end',out+part,'gzip-truncated')
                    out.extend(part)
                    p = len(data)-len(d.unused_data)
                except zlib.error as e:raise CodecError(str(e),out,'gzip')
            elif chunk.startswith(b'\xfd7zXZ\x00') or (len(chunk)>=13 and chunk[0] == 0x5d and chunk[1] == 0):
                try:
                    d = lzma.LZMADecompressor(format=lzma.FORMAT_AUTO)
                    part = d.decompress(chunk)
                    if not d.eof:raise CodecError('premature end',out+part,'lzma-truncated')
                    out.extend(part)
                    p = len(data)-len(d.unused_data)
                except lzma.LZMAError as e:raise CodecError(str(e),out,'lzma')
            elif passthrough:
                out.extend(chunk);break
            else:
                raise CodecError('unknown header' if len(chunk)<4 else 'unsupported format',out,'format')
        return bytes(out)
    def report_decode_error(self,e,name):
        if e.kind == 'format':self.err(f'zstd: {name}: {e} \n')
        elif e.kind == 'truncated':self.err(f'{name} : Read error (39) : premature end \n')
        elif e.kind == 'memory':
            self.err(f'{name} : Decoding error (36) : Frame requires too much memory for decoding \n')
            mb = (e.window+1048575)//1048576
            self.err(f'{name} : Window size larger than maximum : {e.window} > {self.o.memory} \n',2)
            self.err(f'{name} : Use --long={max(10,(e.window-1).bit_length())} or --memory={mb}MB \n',2)
        elif e.kind == 'gzip-truncated':self.err(f'{name} : Read error : premature end \n')
        elif e.kind == 'gzip':self.err(f'{name} : gzip decompression error : incorrect data check \n')
        elif e.kind.startswith('lzma'):self.err(f'{name} : lzma decompression error \n')
        else:self.err(f'{name} : Decoding error (36) : {e} \n')
    def status(self,src,dst,n,c,total=False):
        o = self.o
        level = 3 if total else 2
        if o.to_stdout or dst == '-':level = 3
        if self.multi:level = 3
        if o.verbosity < level:return
        if o.mode == 'compress':
            ratio = f'{100*c/n:6.2f}%  ' if n else ' '
            target = STDOUT if dst == '-' else dst
            self.err(f'{src:<20} :{ratio} ({progress_size(n,o.verbosity>=4)} => {progress_size(c,o.verbosity>=4)}, {target}) \n',level)
        else:
            self.err(f'{src:<19}: {n} bytes \n',level)
    def process(self,p,outfile=None):
        o = self.o
        if o.exclude and o.mode == 'compress' and any(p.endswith(s) for s in SUFFIXES+['.bz2','.zip','.lz4','.7z']):return False
        st = self.stat_input(p)
        if st is False:self.failed = True;return False
        dst = self.output_name(p)
        if dst is False:self.failed = True;return False
        if outfile is None and not self.allow_output(dst,p):self.failed = True;return False
        name = STDIN if p == '-' else p
        if p == '-' and sys.stdin.isatty() and not o.force:
            self.err('zstd: Refusing to read from a console, please specify a file.\nzstd: For help, type: zstd -h\n');self.failed = True;return False
        if dst == '-' and sys.stdout.isatty() and not (o.force or o.to_stdout):
            self.err('zstd: Refusing to write compressed data to a console, please redirect output.\nzstd: For help, type: zstd -h\n');self.failed = True;return False
        f = outfile
        own = False
        if dst not in (None,'-') and f is None:
            try:f = open(dst,'wb');own = True
            except OSError as e:
                self.err(f'zstd: {dst}: {e.strerror}\n');self.failed = True;return False
        try:
            if p == '-':data = self.read_stdin();known = False
            else:
                try:data = Path(p).read_bytes();known = stat.S_ISREG(st.st_mode)
                except OSError as e:
                    self.err(f'zstd: {p}: {e.strerror} \n');self.failed = True;return False
            if o.verbosity >= 4 and dst == '-':
                self.err('Using stdout for output \n',4)
                if o.mode != 'compress' and o.sparse is None:self.err('Sparse File Support is automatically disabled on stdout ; try --sparse \n',4)
            if o.mode == 'compress':
                result = self.encode(data,known)
                n,c = len(data),len(result)
                if o.verbosity >= 4 and o.fmt == 'zstd':
                    h = FrameHeader(result)
                    self.err(f'Decompression will require {max(1,h.window)} B of memory\n',4)
            else:
                result = self.decode(data)
                n,c = len(result),len(data)
            if dst == '-':sys.stdout.buffer.write(result);sys.stdout.buffer.flush()
            elif f is not None:
                f.write(result);f.flush()
            self.cnt += 1
            self.total_in += n;self.total_out += c
            self.status(name,dst,n,c)
            if own and st is not None:
                try:
                    os.chmod(dst,stat.S_IMODE(st.st_mode)&0o777)
                    os.utime(dst,ns=(st.st_atime_ns,st.st_mtime_ns))
                except OSError:pass
            if not o.keep and dst not in (None,'-') and p != '-':
                try:os.unlink(p)
                except OSError as e:self.err(f'zstd: {p}: {e.strerror} \n');self.failed = True
            return True
        except CodecError as e:
            if dst == '-':sys.stdout.buffer.write(e.partial);sys.stdout.buffer.flush()
            elif f is not None:f.write(e.partial)
            self.report_decode_error(e,name)
            self.failed = True
            if own:
                f.close()
                try:os.unlink(dst)
                except OSError:pass
            return False
        except (OSError,BrokenPipeError) as e:
            self.err(f'zstd: {dst}: {getattr(e,"strerror",str(e))}\n');self.failed = True;return False
        finally:
            if own and f is not None and not f.closed:f.close()
    def run(self):
        self.parse()
        o = self.o
        self.err(BANNER,3)
        if o.mode == 'list':return self.list_files()
        if o.mode == 'train':return self.train()
        if o.mode == 'bench':return self.benchmark()
        self.parameter_checks()
        self.dictionary = self.read_dictionary()
        files = self.expand_files()
        if not files:
            if o.recurse and o.files:return 1 if self.failed else 0
            files = ['-']
        self.multi = len(files)>1
        combined = None
        if self.multi and (o.to_stdout or o.output):
            if o.to_stdout or o.output == '-':
                self.err('zstd: WARNING: all input files will be processed and concatenated into stdout. \nThe concatenated output CANNOT regenerate original file names nor directory structure. \n',3)
            else:
                self.err(f'zstd: WARNING: all input files will be processed and concatenated into a single output file: {o.output} \nThe concatenated output CANNOT regenerate original file names nor directory structure. \n',2)
                if not o.force:
                    if o.verbosity < 2:self.fatal('Concatenating multiple processed inputs into a single output loses file metadata. \nAborting. \n')
                    self.err('Proceed? (y/n): ')
                    ans = sys.stdin.readline()
