        for p in files:self.process(p,combined)
        if combined is not None:combined.close()
        if self.multi and self.cnt:
            level = 3 if o.to_stdout or o.output == '-' else 2
            if o.mode == 'compress':
                ratio = 100*self.total_out/self.total_in if self.total_in else 0
                self.err(f'{self.cnt:3} files compressed : {ratio:6.2f}% ({progress_size(self.total_in,o.verbosity>=4,True)} => {progress_size(self.total_out,o.verbosity>=4,True)})\n',level)
            else:self.err(f'{self.cnt} files decompressed : {self.total_in:6} bytes total \n',level)
