        return 1 if self.failed else 0

    def get_frame_info(self,path):
        try:
            if not os.path.isfile(path):
                self.err(f'Error : {path} is not a file \n');return None,True
            data = Path(path).read_bytes()
        except OSError:
            self.err(f'Error : {path} is not a file \n');return None,True
        info = dict(frames=0,skips=0,csize=len(data),usize=0,window=0,dictid=0,check=False,checksum=None)
        p = 0
        if not data:
            self.err('Error: reached end of file with incomplete frame \n')
            return 'invalid',True
        failed = False
        while p < len(data):
            if p+4>len(data):
                self.err('Error: reached end of file with incomplete frame \n');return 'invalid',True
            magic = int.from_bytes(data[p:p+4],'little')
            if magic & 0xfffffff0 == 0x184d2a50:
                if p+8>len(data):
                    self.err('Error: reached end of file with incomplete frame \n');return 'invalid',True
                size = int.from_bytes(data[p+4:p+8],'little')
                p += 8+size
                info['skips'] += 1
                continue
            if data[p:p+4] != MAGIC:return 'invalid',True
            try:h = FrameHeader(data,p)
            except CodecError:
                self.err('Error: reached end of file with incomplete frame \n');return 'invalid',True
            info['window'] = h.window
            info['dictid'] = h.dictid
            info['check'] = h.check
            if h.size is None or info['usize'] is None:info['usize'] = None
            else:info['usize'] += h.size
            p = h.end
            while True:
                if p+3>len(data):
                    self.err('Error: could not read block header \n');failed = True;break
                bh = int.from_bytes(data[p:p+3],'little');p += 3
                size,ty,last = bh>>3,(bh>>1)&3,bh&1
                if ty == 3:
                    self.err('Error: invalid block type \n');failed=True;break
                p += 1 if ty==1 else size
                if last:break
            if failed:break
            if h.check:
                if p+4>len(data):
                    self.err('Error: could not read checksum \n');failed=True;break
                info['checksum'] = int.from_bytes(data[p:p+4],'little')
                p += 4
            info['frames'] += 1
        if failed:self.err(f'Error while parsing "{path}" \n')
        return info,failed
    def list_files(self):
        o = self.o
        files = self.expand_files()
        if not files or '-' in files:
            self.err('zstd: --list does not support reading from standard input \n')
            if not files:self.err('No files given \n')
            return 1
        verbose = o.verbosity >= 3
        raw = o.verbosity >= 4
        if not verbose:sys.stdout.write('Frames  Skips  Compressed  Uncompressed  Ratio  Check  Filename\n')
        total = dict(frames=0,skips=0,csize=0,usize=0,check=False)
        valid = 0
        failed = False
        def row(info,name):
            n,c = info['usize'],info['csize']
            ratio = n/c if c and n is not None else 0
            left = f"{info['frames']+info['skips']:6}  {info['skips']:5}  {list_size(c,raw)}"
            mid = f'  {list_size(n,raw):>12}  {ratio:5.3f}' if n is not None else ' '*21
            return left+mid+f"  {'XXH64' if info['check'] else 'None':>5}  {name}\n"
        for p in files:
            info,bad = self.get_frame_info(p)
            failed |= bad
            if info == 'invalid':sys.stdout.write(f'File "{p}" not compressed by zstd \n')
            elif info is not None:
                n,c = info['usize'],info['csize']
                if verbose:
                    sys.stdout.write(f"{p} \n# Zstandard Frames: {info['frames']}\n")
                    if info['skips']:sys.stdout.write(f"# Skippable Frames: {info['skips']}\n")
                    sys.stdout.write(f"DictID: {info['dictid']}\nWindow Size: {human(info['window'],raw)} ({info['window']} B)\nCompressed Size: {human(c,raw)} ({c} B)\n")
                    if n is not None:
                        sys.stdout.write(f'Decompressed Size: {human(n,raw)} ({n} B)\nRatio: {n/c if c else 0:.4f}\n')
                    cs = 'XXH64' if info['check'] else 'None'
                    if info['frames'] == 1 and info['check'] and info['checksum'] is not None:cs += f" {info['checksum']:08x}"
                    sys.stdout.write('Check: '+cs+'\n')
                else:sys.stdout.write(row(info,p))
                for k in ('frames','skips','csize'):total[k] += info[k]
                if info['usize'] is None:total['usize'] = None
                elif total['usize'] is not None:total['usize'] += info['usize']
                total['check'] = total['check'] or info['check']
                valid += 1
            if verbose:sys.stdout.write('\n')
        if len(files)>1 and not verbose:
            sys.stdout.write('----------------------------------------------------------------- \n')
            sys.stdout.write(row(total,f'{len(files)} files'))
        return 1 if failed else 0

    def train(self):
        files = self.expand_files()
        samples = []
        for p in files:
            try:
                if p == '-':continue
                d = Path(p).read_bytes()
                if self.o.split:
                    samples.extend(d[i:i+self.o.split] for i in range(0,len(d),self.o.split))
                else:samples.append(d)
            except OSError:pass
        if len(samples)<5:
            self.err('!  Warning : nb of samples too low for proper processing !\n!  Please provide _one file per sample_.\n!  Alternatively, split file(s) into fixed-size samples, with --split=#\n',2)
            self.fatal('Error 14 : nb of samples too low\n',14)
        self.err(f'WARNING: The maximum dictionary size {self.o.maxdict} is too large compared to the source size {sum(map(len,samples))}! size(source)/size(dictionary) = {sum(map(len,samples))/max(1,self.o.maxdict):.6f}, but it should be >= 10! This may lead to a subpar dictionary! We recommend training on sources at least 10x, and preferably 100x the size of the dictionary! \n',2)
        self.fatal('dictionary training failed : Src size is incorrect \n')
    def benchmark(self):
        self.dictionary = self.read_dictionary()
        files = self.expand_files()
        for p in files:
            if self.stat_input(p) is False:return 1
        if not files:
            self.err('Using synthetic 50% compressible data of 10 MB size \n',2)
        return 0

def main():
    try:
        result = App(sys.argv[1:]).run()
    except Stop as e:
        result = e.code
    except KeyboardInterrupt:
        result = 2
    except BrokenPipeError:
        result = 1
    sys.exit(result)

if __name__ == '__main__':
    main()
