def write_normalized(norm, log):
    writer = BitWriter()
    writer.add(log-5,4)
    remaining = (1 << log)+1
    threshold = 1 << log
    bits = log+1
    pos = 0
    while remaining>1 and pos<len(norm):
        n = norm[pos]
        maximum = 2*threshold-1-remaining
        value = n+1
        if value < maximum:
            writer.add(value,bits-1)
        else:
            if value >= threshold:
                value += maximum
            writer.add(value,bits)
        remaining -= abs(n)
        pos += 1
        while remaining < threshold:
            bits -= 1
            threshold >>= 1
        if n == 0:
            run = 0
            while pos<len(norm) and norm[pos] == 0:
                run += 1;pos += 1
            while run >= 3:
                writer.add(3,2);run -= 3
            writer.add(run,2)
    return writer.finish(False)


def normalize_counts(counts,log,low_negative=False):
    total = sum(counts)
    size = 1 << log
    if not total:
        raise CodecError()
    cutoff = [0,.451,.481,.497,.525,.668,.716,.792]
    norm = []
    for c in counts:
        if not c:
            norm.append(0)
        elif c <= total//size:
            norm.append(-1 if low_negative else 1)
        else:
            x = c*size/total
            n = int(x)
            if n<8 and x-n>cutoff[n]:n += 1
            norm.append(max(1,n))
    diff = size-sum(abs(n) for n in norm)
    biggest = max(range(len(counts)),key=lambda s:counts[s])
    if norm[biggest]+diff>0:
        norm[biggest] += diff
    else:
        # For very flat alphabets distribute the remaining states by their
        # fractional shares, keeping every present symbol represented.
        norm = [1 if c else 0 for c in counts]
        for _ in range(size-sum(norm)):
            s = max(range(len(counts)),key=lambda j:counts[j]/max(1,norm[j]+.5))
            norm[s] += 1
        if low_negative:
            norm = [-1 if v==1 and c<=total//size else v for c,v in zip(counts,norm)]
    return norm


def encode_fse_bytes(data,norm=None,log=5):
    if len(data)<2:
        return b''
    if norm is None:
        counts = [0]*(max(data)+1)
        for x in data:counts[x] += 1
        norm = normalize_counts(counts,log)
    table = table_from_normalized(norm,log)
    writer = BitWriter()
    states = [0,0]
    for parity in (0,1):
        index = len(data)-1
        if index%2 != parity:index -= 1
        states[parity] = table.initial(data[index])
    for index in range(len(data)-3,-1,-1):
        parity = index%2
        states[parity] = table.encode(states[parity],data[index],writer)
    writer.add(states[1],log)
    writer.add(states[0],log)
    return write_normalized(norm,log)+writer.finish()


def huffman_lengths(counts,limit):
    import heapq
    leaves = [(n,1,-s,s) for s,n in enumerate(counts) if n]
    if len(leaves)<2:
        return [1 if c else 0 for c in counts]
    heap = list(leaves)
    heapq.heapify(heap)
    serial = 0
    while len(heap)>1:
        a,b = heapq.heappop(heap),heapq.heappop(heap)
        heapq.heappush(heap,(a[0]+b[0],0,serial,(a[3],b[3])))
        serial += 1
    lengths = [0]*len(counts)
    def walk(x,depth):
        if isinstance(x,int):lengths[x] = depth
        else:walk(x[0],depth+1);walk(x[1],depth+1)
    walk(heap[0][3],0)
    if max(lengths)<=limit:
        return lengths
    # Bounded-length codes via a package merge on symbol weights.
    # Sorting leaves ahead of equal-cost packages favors balanced rare codes.
    nodesfirst = sum(1 for c in counts if c==1)<3
    leaves = sorted([(n,1 if nodesfirst else 0,-s,s) for s,n in enumerate(counts) if n])
    previous = leaves
    for _ in range(1,limit):
        packages = []
        for j in range(0,len(previous)-1,2):
            a,b = previous[j:j+2]
            packages.append((a[0]+b[0],0 if nodesfirst else 1,j,(a[3],b[3])))
        previous = sorted(leaves+packages,key=lambda t:t[:3])[:2*len(leaves)-2]
    lengths = [0]*len(counts)
    def add(x):
        if isinstance(x,int):lengths[x] += 1
        else:add(x[0]);add(x[1])
    for x in previous[:2*len(leaves)-2]:add(x[3])
    return lengths


def huffman_description(weights):
    encoded = encode_fse_bytes(weights[:-1]) if len(set(weights[:-1]))>1 else b''
    count = len(weights)-1
    raw = None
    if 1<=count<=128:
        raw = bytearray([count+127])
        for i in range(0,count,2):
            raw.append((weights[i]<<4) | (weights[i+1] if i+1<count else 0))
        raw = bytes(raw)
    if encoded and len(encoded)<128 and (raw is None or len(encoded)+1<len(raw)):
        return bytes([len(encoded)])+encoded
    if raw is not None:return raw
    raise CodecError()


def encode_literals(literals,allow=True,old_table=None):
    n = len(literals)
    raw = literals_raw(literals)
    if not allow or n < 6:
        return raw,None
    counts = collections.Counter(literals)
    if len(counts)==1:
        if n<32:header = bytes([(n<<3)|1])
        elif n<4096:header = ((n<<4)|5).to_bytes(2,'little')
        else:header = ((n<<4)|13).to_bytes(3,'little')
        return header+literals[:1],None
    if n < 64:
        return raw,None
    cs = [counts[i] for i in range(max(counts)+1)]
    limit = max((len(counts)-1).bit_length(),min(11,(n-1).bit_length()-2))
    lengths = huffman_lengths(cs,limit)
    depth = max(lengths)
    weights = [depth+1-l if l else 0 for l in lengths]
    table = HuffmanTable(weights[:-1])
    try:description = huffman_description(weights)
    except CodecError:return raw,None
    def stream(part):
        bw = BitWriter()
        for sym in reversed(part):
            val,bits = table.encode[sym]
            bw.add(val,bits)
        return bw.finish()
    if n<256:
        payload = stream(literals)
        fmt = 0
    else:
        chunk = (n+3)//4
        parts = [stream(literals[i*chunk:min((i+1)*chunk,n)]) for i in range(4)]
        payload = struct.pack('<3H',*(len(x) for x in parts[:3]))+b''.join(parts)
        fmt = 1 if n<1024 else (2 if n<16384 else 3)
    packed = description+payload
    csize = len(packed)
    if n<1024 and csize<1024:
        hs = 3;sizebits = 10
    elif n<16384 and csize<16384:
        fmt = 2;hs = 4;sizebits = 14
    else:
        fmt = 3;hs = 5;sizebits = 18
    hdr = (2+(fmt<<2)+(n<<4)+(csize<<(4+sizebits))).to_bytes(hs,'little')
    result = hdr+packed
    if len(result)>=len(raw)-(n>>6)-2:
        return raw,None
    return result,table
